$('saveCommissionSettings').addEventListener('click',()=>{const per=Number($('settingsCommissionPerScan').value),pct=Number($('settingsCommissionSalesRate').value);if(!Number.isFinite(per)||per<0||!Number.isFinite(pct)||pct<0){$('commissionSettingsStatus').textContent='Enter valid non-negative commission rates.';return}localStorage.setItem(COMMISSION_RATE_KEY,JSON.stringify({perScan:per,salesPercent:pct}));renderCommissionSettings();$('commissionSettingsStatus').textContent='Commission rates saved and included in your next backup.';persist(true);status('Commission rates updated in App Settings.')});
