async function handleDriveAuthReturn(){const params=new URLSearchParams(location.search),ticket=params.get('drive_ticket'),auth=params.get('drive_auth');if(!ticket&&!auth)return;if(auth==='error'){history.replaceState({},document.title,location.pathname+location.hash);const reason=params.get('drive_reason');driveStatus('Google authorisation was not completed. '+(reason||'Please check the Worker and Google OAuth setup, then try again.'),'Not connected');return}if(!ticket)return;try{const result=await workerRequest('/auth/exchange',{method:'POST',body:JSON.stringify({ticket})});history.replaceState({},document.title,location.pathname+location.hash);driveSession=result.sessionToken;localStorage.setItem(DRIVE_SESSION_KEY,driveSession);$('driveBackupNow').disabled=false;$('driveRestore').disabled=false;driveStatus('Google Drive connected securely. Preparing your first backup…','Connected');await performDriveBackup()}catch(err){driveStatus('Could not finish Google authorisation. '+err.message+' You can refresh this page to retry while the one-time ticket is still valid.','Error')}}
async function restoreDriveSession(){driveSession=localStorage.getItem(DRIVE_SESSION_KEY)||'';if(!driveSession)return;try{const result=await workerRequest('/status',{method:'GET'});$('driveBackupNow').disabled=false;$('driveRestore').disabled=false;driveStatus(result.lastBackupAt?'Connected · Last backup '+new Date(result.lastBackupAt).toLocaleString('en-GB'):'Connected. No cloud backup has completed yet.','Connected');if(localStorage.getItem(DRIVE_PENDING_KEY)==='1')performDriveBackup()}catch(err){if(err.status===401){driveSession='';localStorage.removeItem(DRIVE_SESSION_KEY);$('driveBackupNow').disabled=true;$('driveRestore').disabled=true;driveStatus('Google Drive needs reconnecting. Your diary remains saved locally. '+err.message,'Reconnect')}else{driveStatus('Could not check Google Drive just now. Your saved connection has been kept; it will retry when you are online. '+err.message,'Waiting')}}}
