function load(){try{const raw=localStorage.getItem(STORE);if(raw){const s=JSON.parse(raw);if(s&&s.appId===APP_ID){applyCurrentShift(s);state.archivedShifts=Array.isArray(s.archivedShifts)?s.archivedShifts:[]}}}catch(err){console.warn('Saved shift could not be read',err);status('Saved data could not be read.')}render();renderArchivedShifts()}
function linkedHeadcodes(record){const valid=v=>{const h=String(v||'').trim().toUpperCase().replace(/^\[|\]$/g,'');return /^[0-9][A-Z][0-9]{2}$/.test(h)?h:''};const values=[...(Array.isArray(record?.relatedTrainHeadcodes)?record.relatedTrainHeadcodes:[]),record?.relatedTrainHeadcode,record?.headcode,record?.trainHeadcode];if(Array.isArray(record?.relatedTrainIds))for(const id of record.relatedTrainIds){const t=state.trains.find(x=>x.id&&x.id===id);values.push(t?.headcode)}if(record?.relatedTrainId){const t=state.trains.find(x=>x.id&&x.id===record.relatedTrainId);values.push(t?.headcode)}const label=String(record?.relatedTrainLabel||'');values.push(...(label.match(/\b\d[A-Z]\d{2}\b/gi)||[]));if(!values.some(valid)){const text=String(record?.text||'');values.push(...(text.match(/\[([0-9][A-Z][0-9]{2})\]/gi)||[]).map(x=>x.slice(1,-1)))}return [...new Set(values.map(valid).filter(Boolean))]};function linkedHeadcode(record){return linkedHeadcodes(record)[0]||''}
function entryDetails(e){const headcodes=linkedHeadcodes(e);const stripRepeatedHeadcode=value=>{let text=String(value||'No details recorded').replace(/\\n/g,'\n');for(const hc of headcodes)text=text.replace(new RegExp('\\['+hc+'\\]','gi'),'');return text.split('\n').map(line=>line.replace(/^\s*[-–—:|]\s*/, '').replace(/\s*[-–—:|]\s*$/, '').replace(/[ \t]{2,}/g,' ').trim()).join('\n')};const updates=Array.isArray(e.updates)?e.updates.map(u=>`\n\nUPDATE — ${fmt(u.timestamp)}\n${stripRepeatedHeadcode(u.text)}`):[];const passengerMeta=e.type==='Passenger Counts'?[...(e.fullStanding===true?['Full and standing']:[]),...(Array.isArray(e.trainSets)&&e.trainSets.length?[`Train set: ${e.trainSets.join(', ')}`]:[])]:[];return [...headcodes.map(h=>`[${h}]`),...(e.logNumber?[`Log / reference number: ${e.logNumber}`]:[]),...(e.type==='Incident'&&e.incidentLocation?[`Incident location: ${e.incidentLocation}`]:[]),stripRepeatedHeadcode(e.text),...passengerMeta,...updates].join('\n')}
function entryDetailsHtml(e,includeLeadingHeadcode=true){const lines=entryDetails(e).split('\n');const headcode=linkedHeadcode(e);if(!includeLeadingHeadcode&&headcode&&lines[0]===`[${headcode}]`)lines.shift();return lines.map(line=>line.split(/(\[[0-9][A-Z][0-9]{2}\])/gi).map(part=>/^\[[0-9][A-Z][0-9]{2}\]$/i.test(part)?`<strong class="headcode-highlight" style="color:#c00035 !important;font-weight:900 !important">${esc(part.toUpperCase())}</strong>`:esc(part)).join('')).join('<br>')}
function defectMeta(e){if(e?.type!=='Defect')return null;const text=String(e.text||'');const unit=(text.match(/\bUnit\s+(\d{6})\b/i)||[])[1]||'';const pvn=(text.match(/\bPVN\s+(\d+)\b/i)||[])[1]||'';return unit?{unit,pvn,headcode:linkedHeadcode(e)}:null}
function groupedEntries(entries){const defectGroups=new Map(),passengerGroups=new Map();entries.forEach((e,index)=>{const meta=defectMeta(e);if(meta){if(!defectGroups.has(meta.unit))defectGroups.set(meta.unit,{meta:{unit:meta.unit},items:[]});defectGroups.get(meta.unit).items.push({entry:e,index,meta})}if(e.type==='Passenger Counts'){const hc=linkedHeadcode(e)||'NO-HEADC0DE';if(!passengerGroups.has(hc))passengerGroups.set(hc,{headcode:hc,items:[]});passengerGroups.get(hc).items.push({entry:e,index})}});const firstIndex=new Map(),consumed=new Set();for(const g of defectGroups.values())if(g.items.length>1){firstIndex.set(g.items[0].index,{kind:'defectGroup',meta:g.meta,items:g.items});g.items.slice(1).forEach(x=>consumed.add(x.index))}for(const g of passengerGroups.values())if(g.items.length>=1){firstIndex.set(g.items[0].index,{kind:'passengerGroup',headcode:g.headcode,items:g.items});g.items.slice(1).forEach(x=>consumed.add(x.index))}const out=[];entries.forEach((entry,index)=>{if(consumed.has(index))return;out.push(firstIndex.get(index)||{kind:'single',entry,index})});return out}
function passengerStationName(value){let name=String(value||'').trim();if(!name)return 'Location not recorded';name=name.replace(/\s*(?:[·|,;—-]\s*)?(?:Train portion|Applies to)\s*:\s*.*$/i,'').trim();name=name.replace(/\s*\([A-Z]{3}\)\s*$/,'').trim();return name||'Location not recorded'}
function passengerGroupRows(group){return group.items.map(x=>{const text=String(x.entry.text||'');return {station:passengerStationName((text.match(/Location:\s*([^\n]+)/i)||[])[1]),first:Number((text.match(/First Class:\s*(\d+)/i)||[])[1])||0,standard:Number((text.match(/Standard Class:\s*(\d+)/i)||[])[1])||0,formation:x.entry.trainSets?.[0]||((text.match(/(?:Applies to|Train portion):\s*([^\n]+)/i)||[])[1]?.trim())||'Whole Train',fullStanding:x.entry.fullStanding===true,entry:x.entry}})}
async function copyPassengerGroupTable(group){const rows=passengerGroupRows(group);const heading=`Passenger Counts${group.headcode!=='NO-HEADC0DE'?' — '+group.headcode:''}`;const text=[heading,'Station | First Class | Standard Class',...rows.map(r=>`${r.station} | ${r.first} | ${r.standard}${r.fullStanding?' | FULL AND STANDING':''}`)].join('\n');try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else fallbackCopy(text);status('Passenger count table copied to clipboard.')}catch(err){try{fallbackCopy(text);status('Passenger count table copied to clipboard.')}catch(e){status('Could not copy passenger count table. Check clipboard permissions.')}}}
function passengerGroupHtml(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?{entry:x.entry,text:m[1].trim()}:null}).filter(Boolean);return `<article class="entry passenger-count-group"><div class="entrytop"><span> #️⃣ PASSENGER COUNTS${group.headcode!=='NO-HEADC0DE'?` <strong class="headcode-highlight">[${esc(group.headcode)}]</strong>`:''} <span class="incident-ref-marker">${group.items.length} entries</span><button type="button" class="entry-action passenger-copy-table" data-copy-passenger-table="${esc(group.headcode)}" aria-label="Copy passenger count table" title="Copy passenger count table">📋</button><button type="button" class="entry-action passenger-delete-train" data-delete-passenger-train="${esc(group.headcode)}" aria-label="Delete all passenger counts for this train" title="Delete all counts for this train">🗑️</button></span><time>${esc(fmt(group.items[0].entry.timestamp))}</time></div><div class="passenger-table-wrap"><table class="passenger-count-table"><thead><tr><th>Station</th><th>First Class</th><th>Standard Class</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.fullStanding?'full-standing-row':''}"><td>${esc(r.station)}</td><td>${r.first}</td><td>${r.standard}</td></tr>`).join('')}</tbody></table></div>${notes.length?`<section class="passenger-notes"><h4>📝 Notes for ${group.headcode!=='NO-HEADC0DE'?esc(group.headcode):'this train'}</h4>${notes.map(n=>`<p><strong>${esc(fmt(n.entry.timestamp))}${group.headcode!=='NO-HEADC0DE'?' · '+esc(group.headcode):''}</strong><br>${esc(n.text).replace(/\n/g,'<br>')}</p>`).join('')}</section>`:''}${group.items.filter(x=>x.entry.fullStanding).map(x=>`<p class="full-standing-note">🔴 FULL AND STANDING · ${esc(fmt(x.entry.timestamp))} · ${esc(group.headcode)}</p>`).join('')}${group.items.map(x=>`<details><summary>${esc(fmt(x.entry.timestamp))} · ${esc((String(x.entry.text||'').match(/Location:\s*([^\n]+)/i)||[])[1]||'Location not recorded')} <button type="button" class="entry-action passenger-edit-trigger" data-edit-passenger="${x.index}" aria-label="Edit passenger count" title="Edit passenger count">✏️</button> <button type="button" class="entry-action passenger-delete-trigger" data-delete-passenger="${x.index}" aria-label="Delete this passenger count" title="Delete this passenger count">🗑️</button></summary><p>${entryDetailsHtml(x.entry,false)}</p></details>`).join('')}</article>`} 

function defectDetailText(e,meta){let text=entryDetails(e);const headcode=linkedHeadcode(e);if(headcode&&text.startsWith(`[${headcode}]\n`))text=text.slice(headcode.length+3);return text.split('\n').map(line=>line.replace(new RegExp('\\s*[·|]\\s*Unit\\s+'+(meta.unit||'')+'\\b','i'),'').replace(/\s*[·|]\s*PVN\s+\d+\b/i,'').replace(/[ \t]{2,}/g,' ').trim()).join('\n')}
function passengerGroupPdfHtml(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?{entry:x.entry,text:m[1].trim()}:null}).filter(Boolean);return `<div class="passenger-pdf-report"><table class="passenger-count-table" style="width:100%;border-collapse:collapse;margin:8px 0 12px;font-size:13px"><thead><tr><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:left">Station</th><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:center">First Class</th><th style="background:#f1e8ec;color:#241821;border:1px solid #cfc5ca;padding:7px;text-align:center">Standard Class</th></tr></thead><tbody>${rows.map(r=>`<tr${r.fullStanding?' style="background:#ffe5e7;color:#8f001f;font-weight:700"':''}><td style="border:1px solid #cfc5ca;padding:7px">${esc(r.station)}</td><td style="border:1px solid #cfc5ca;padding:7px;text-align:center">${r.first}</td><td style="border:1px solid #cfc5ca;padding:7px;text-align:center">${r.standard}</td></tr>`).join('')}</tbody></table>${notes.length?`<div class="passenger-pdf-notes"><strong>Notes${group.headcode!=='NO-HEADC0DE'?' — '+esc(group.headcode):''}</strong>${notes.map(n=>`<p style="margin:4px 0"><b>${esc(fmt(n.entry.timestamp))}</b><br>${esc(n.text).replace(/\n/g,'<br>')}</p>`).join('')}</div>`:''}${group.items.filter(x=>x.entry.fullStanding).map(x=>`<p style="margin:4px 0;color:#8f001f;font-weight:700">FULL AND STANDING — ${esc(fmt(x.entry.timestamp))}${group.headcode!=='NO-HEADC0DE'?' — '+esc(group.headcode):''}</p>`).join('')}</div>`}
function passengerGroupPlain(group){const rows=passengerGroupRows(group);const notes=group.items.map(x=>{const m=String(x.entry.text||'').match(/^Notes(?:\s*\([^\n]*?\))?:\s*([\s\S]*?)(?=\n[A-Z][^\n]*:|$)/im);return m&&m[1].trim()?`     ${fmt(x.entry.timestamp)}${group.headcode!=='NO-HEADC0DE'?' · '+group.headcode:''}: ${m[1].trim()}`:null}).filter(Boolean);const standing=rows.filter(r=>r.fullStanding).map(r=>`     🔴 FULL AND STANDING · ${fmt(r.entry.timestamp)}${group.headcode!=='NO-HEADC0DE'?' · '+group.headcode:''}`);return `#️⃣ PASSENGER COUNTS${group.headcode!=='NO-HEADC0DE'?' — '+group.headcode:''}\nStation | First Class | Standard Class\n${rows.map(r=>`${r.station} | ${r.first} | ${r.standard}${r.fullStanding?' | FULL AND STANDING':''}`).join('\n')}${notes.length?'\n\n📝 NOTES\n'+notes.join('\n'):''}${standing.length?'\n\n'+standing.join('\n'):''}` }
function defectGroupPlain(group){const {meta,items}=group;const byPvn=new Map();items.forEach(x=>{const pvn=x.meta.pvn||'PVN not recorded';if(!byPvn.has(pvn))byPvn.set(pvn,[]);byPvn.get(pvn).push(x)});return `🔧 DEFECTS — UNIT ${meta.unit} (${items.length})\n${[...byPvn].map(([pvn,list])=>`     ${pvn==='PVN not recorded'?pvn:`PVN ${pvn}`}\n${list.map((x,i)=>`       Defect ${i+1}${x.meta.headcode?` [${x.meta.headcode}]`:''} · ${fmt(x.entry.timestamp)}\n${defectDetailText(x.entry,meta).split('\n').map(line=>'          '+line).join('\n')}`).join('\n')}`).join('\n')}`}
function defectGroupHtml(group){const {meta,items}=group;const byPvn=new Map();items.forEach(x=>{const pvn=x.meta.pvn||'PVN not recorded';if(!byPvn.has(pvn))byPvn.set(pvn,[]);byPvn.get(pvn).push(x)});let n=0;return `<article class="entry defect-group"><div class="entrytop"><span>🔧 DEFECTS (${items.length})</span><time>${esc(fmt(items[0].entry.timestamp))}</time></div><div class="defect-group-meta">UNIT ${esc(meta.unit)}</div>${[...byPvn].map(([pvn,list])=>`<section class="defect-pvn-group"><div class="defect-pvn-heading">${pvn==='PVN not recorded'?pvn:`PVN ${esc(pvn)}`}</div>${list.map(x=>{n++;return `<div class="defect-group-item"><div class="defect-group-item-head"><strong>Defect ${n}${x.meta.headcode?` · <span class="headcode-highlight">${esc(x.meta.headcode)}</span>`:''}</strong><time>${esc(fmt(x.entry.timestamp))}${x.entry.editedAt?' · Edited':''}</time><button type="button" class="entry-action entry-menu-trigger" data-entry-menu="${x.index}" aria-label="More options for defect ${n}">⋯</button></div><p>${esc(defectDetailText(x.entry,meta)).replace(/\n/g,'<br>')}</p></div>`}).join('')}</section>`).join('')}</article>`}

function renderArchiveCalendar(){
 const host=$('archiveCalendarDays');if(!host)return;const y=archiveCalendarMonth.getFullYear(),m=archiveCalendarMonth.getMonth();$('archiveCalTitle').textContent=archiveCalendarMonth.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
 const first=new Date(y,m,1),offset=first.getDay(),days=new Date(y,m+1,0).getDate();const byDate=new Map();state.archivedShifts.forEach(r=>{const d=String(r.shift?.date||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(d))return;if(!byDate.has(d))byDate.set(d,[]);byDate.get(d).push(r)});
 let html='';for(let i=0;i<offset;i++)html+='<span class="archive-cal-empty"></span>';
 for(let day=1;day<=days;day++){const key=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=byDate.get(key)||[],jobNumbers=items.map(r=>String(r.shift?.jobNumber||'').trim().toUpperCase()),activityType=jobNumbers.some(j=>['REFRESH','ROUTES'].includes(j)),otherActivity=jobNumbers.includes('OTHER'),hasContent=items.some(r=>(r.entries||[]).length||(r.trains||[]).length||String(r.shift?.notes||'').trim()||String(r.shift?.jobNumber||'').trim());html+=`<button type="button" class="archive-cal-day ${hasContent?'has-content':''} ${otherActivity&&!activityType?'activity-blue':''} ${activityType?'activity-yellow':''} ${items.length?'has-archive':''} ${selectedArchiveDate===key?'selected':''}" data-cal-date="${key}" ${items.length?'aria-label="'+day+' '+items.length+' archived shift(s)'+(activityType?', route activity (yellow)':otherActivity?', other activity (light blue)':'')+'"':'disabled'}>${day}${items.length?`<small>${items.length}</small>`:''}</button>`}
 host.innerHTML=html;
}
$('archiveCalPrev').addEventListener('click',()=>{archiveCalendarMonth=new Date(archiveCalendarMonth.getFullYear(),archiveCalendarMonth.getMonth()-1,1);renderArchiveCalendar()});
$('archiveCalNext').addEventListener('click',()=>{archiveCalendarMonth=new Date(archiveCalendarMonth.getFullYear(),archiveCalendarMonth.getMonth()+1,1);renderArchiveCalendar()});
$('archiveCalendarDays').addEventListener('click',e=>{const b=e.target.closest('[data-cal-date]');if(!b)return;selectedArchiveDate=b.dataset.calDate;renderArchivedShifts();const panel=$('archiveDayList');if(panel)panel.open=true;});
function renderArchivedShifts(){
 const list=$('archivedShifts');if(!list)return;const all=state.archivedShifts.slice().sort((a,b)=>String(b.archivedAt||b.updatedAt||'').localeCompare(String(a.archivedAt||a.updatedAt||'')));$('archiveCount').textContent=`${all.length} ${all.length===1?'archived shift':'archived shifts'}`;renderArchiveCalendar();const records=selectedArchiveDate?all.filter(r=>String(r.shift?.date||'').slice(0,10)===selectedArchiveDate):[];const dayTitle=$('archiveDayTitle');if(dayTitle)dayTitle.textContent=selectedArchiveDate?`Shifts on ${dateDMY(selectedArchiveDate)} (${records.length})`:'Select a highlighted day';list.className='archived-shifts '+(records.length?'':'empty');list.innerHTML=records.length?records.map(r=>{const date=dateDMY(r.shift?.date||'');const job=r.shift?.jobNumber||'No turn number';const count=(r.entries?.length||0);const when=r.archivedAt?fmt(r.archivedAt):'Archive date unavailable';return `<article class="archive-record"><div class="archive-record-info"><strong>${esc(date)} · ${esc(job)}</strong><span>${count} ${count===1?'entry':'entries'} · ${esc(when)}</span></div><div class="archive-record-actions"><button type="button" class="secondary" data-view-archive="${esc(r.archiveId||'')}">👁️ View</button><button type="button" class="secondary" data-export-archive="${esc(r.archiveId||'')}">📄 Export PDF</button><button type="button" class="danger" data-delete-archive="${esc(r.archiveId||'')}">Delete</button></div></article>`}).join(''):(selectedArchiveDate?'No archived shifts on this day.':'Select a highlighted calendar day to view its archived shifts.');
}
function downloadJson(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function incidentFallbackNumber(entry){const incidents=state.entries.filter(e=>e.type==='Incident');const index=incidents.findIndex(e=>e.id===entry.id);return entry.incidentNumber||(incidents.reduce((m,e)=>Math.max(m,Number(e.incidentNumber)||0),0)+(index>=0&&!entry.incidentNumber?1:1))}
function incidentTitle(entry){return String(entry.incidentName||'').trim()||`Incident ${incidentFallbackNumber(entry)}`}
function nextIncidentReference(){const job=String($('shiftJobNumber').value||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'');const rawDate=String($('shiftDate').value||nowLocal());const match=rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);const date=match?`${match[3]}${match[2]}${match[1].slice(-2)}`:nowLocal().split('-').reverse().join('').slice(0,6);const prefix=job?`${job}-${date}-`:`${date}-`;const max=state.entries.filter(e=>e.type==='Incident'&&String(e.incidentRef||'').startsWith(prefix)).reduce((n,e)=>Math.max(n,Number(String(e.incidentRef).slice(prefix.length))||0),0);return `${prefix}${String(max+1).padStart(2,'0')}`;}
function reportLines(value){return String(value??'').split('\n').filter(line=>{const t=line.trim();if(!t)return false;return !/^[^:]+:\s*$/.test(t)&&!/^\s*(?:—|-|Not recorded|None recorded|Not specified|No headcode)\s*$/i.test(t)})}
function render(){
 $('trains').className=state.trains.length?'':'empty';
 $('trains').innerHTML=state.trains.length?state.trains.map((t,i)=>`<div class="trainrow"><div><strong>${esc(t.headcode)}</strong><div class="muted">${esc(t.from||'Working')}${/(PASS|TAXI)/i.test(t.from||'')?` · ${esc(t.routeFrom||'—')} → ${esc(t.routeTo||'—')}`:needsUnit(t.from)?' · '+unitText(t):''}</div></div><div class="entry-actions"><button type="button" class="entry-action" data-edit-train="${i}" aria-label="Edit train" title="Edit train">✏️</button><button type="button" class="remove" data-train="${i}" aria-label="Remove train">Remove</button></div></div>`).join(''):'No trains added yet.';
 $('entries').className='entries '+(state.entries.length?'':'empty');
 $('entries').innerHTML=state.entries.length?groupedEntries(state.entries).map(item=>{if(item.kind==='defectGroup')return defectGroupHtml(item);if(item.kind==='passengerGroup')return passengerGroupHtml(item);const e=item.entry,i=item.index;const icons={'General Note':'📝','Update':'📋','Defect':'🔧','Passenger Counts':'#️⃣','Ticket acceptance':'🎟️','Control Message':'📟','Delay':'⏱️','Train Diversion':'🚧','Full and standing':'🛑','Assist':'🦮♿️','Reminder':'ℹ️','Incident':'🚨','Lost Property':'🧳','Late book off':'⌚️','Incident Report':'📄','Incident Report':'📄','Ticket commission':'💷','Shift equipment':'⚙️'};const safety=e.type==='Defect'&&/Safety Critical/i.test(e.text);const cls=[e.type==='Reminder'?'reminder':'',e.type==='Incident'?'incident-entry':'',e.type==='Assist'?'assist-entry':'',e.type==='Control Message'?'control-entry':'',e.type==='Ticket acceptance'?'ticket-acceptance-entry':'',safety?'safety-critical':''].filter(Boolean).join(' ');const heading=(safety?'⚠️ ':'')+(icons[e.type]||'')+' '+(e.type==='Incident'?`INCIDENT — ${incidentTitle(e)}`:String(e.type||'NOTE').toUpperCase());const headcode=linkedHeadcode(e);return `<article class="entry ${cls}"><div class="entrytop"><span>${esc(heading)}${headcode?` <strong class="entry-headcode headcode-highlight">[${esc(headcode)}]</strong>`:''}${e.type==='Incident'&&e.incidentRef?` <span class="incident-ref-marker">${esc(e.incidentRef)}</span>`:''}</span><div class="entry-meta-actions"><time>${esc(fmt(e.timestamp))}${e.editedAt?`<span class="edited-stamp"> · Edited</span>`:''}</time><div class="entry-actions"><button type="button" class="entry-action entry-menu-trigger" data-entry-menu="${i}" aria-label="More options for ${esc(e.type||'log')} entry" title="More options">⋯</button></div></div></div><p>${e.type==='Ticket commission'?entryDetailsHtml({...e,text:String(e.text||'').replace(/^TOTAL COMMISSION:.*\n?/m,'')},false):entryDetailsHtml(e,false)}</p>${e.type==='Ticket commission'&&/TOTAL COMMISSION:\s*£([0-9]+(?:\.[0-9]{2})?)/.test(e.text||'')?`<div class="commission-total-highlight">💷 Total shift commission: <strong>£${Number((String(e.text).match(/TOTAL COMMISSION:\s*£([0-9]+(?:\.[0-9]{2})?)/)||[])[1]).toFixed(2)}</strong></div>`:''}${e.photo?`<img class="entry-photo" src="${e.photo}" alt="Lost property item photo">`:``}</article>`}).join(''):'No log entries yet.';
 $('entryCount').textContent=`${state.entries.length} ${state.entries.length===1?'entry':'entries'}`;
 renderArchivedShifts();
}
function shiftLengthText(on,off){if(!on||!off)return '';const [oh,om]=on.split(':').map(Number),[fh,fm]=off.split(':').map(Number);let n=fh*60+fm-(oh*60+om);if(n<0)n+=1440;return `${Math.floor(n/60)}h ${String(n%60).padStart(2,'0')}m`}
function shiftPayEstimate(){const on=$('bookOn')?.value,off=$('bookOff')?.value,date=$('shiftDate')?.value;if(!on||!off||!date)return null;const [oh,om]=on.split(':').map(Number),[fh,fm]=off.split(':').map(Number);let mins=fh*60+fm-(oh*60+om);if(mins<0)mins+=1440;const sunday=new Date(date+'T12:00:00').getDay()===0,rates=getPayRates(),rate=Number(sunday?rates.sunday:rates.weekday);return {mins,sunday,rate,pay:mins/60*rate}}
function updateShiftLength(){const on=$('bookOn')?.value,off=$('bookOff')?.value,out=$('shiftLength');if(!out)return;out.textContent=on&&off?shiftLengthText(on,off):'Not entered';const line=$('shiftPayEstimate');if(line){const e=shiftPayEstimate();line.textContent=e?`Estimated shift pay: £${e.pay.toFixed(2)} (${e.sunday?'Sunday':'Monday–Saturday'} rate £${e.rate.toFixed(2)}/hour)`:'Estimated shift pay: Enter date, book on and book off times'}}
$('shiftJobNumber').addEventListener('input',()=>persist(true));
