function updateUnitFields(){const job=String($('shiftJobNumber').value||'').trim().toUpperCase(),specialActivity=['REFRESH','ROUTES','OTHER'].includes(job),noHeadcode=specialActivity,activity=$('trainFrom').value,show=needsUnit(activity)&&!specialActivity,route=/(PASS|TAXI)/i.test(activity);$('trainCodeLabel').firstChild.textContent=route?'Headcode or Reference':'Headcode';$('trainCode').required=!noHeadcode;$('trainCode').maxLength=route?40:4;$('trainCode').placeholder=noHeadcode?'N/A':route?'Enter headcode or reference':'1V50';$('unitFields').classList.toggle('hidden',!show);$('unitNumber').required=show;$('trainFrom').disabled=false;$('unitNumber').readOnly=false;$('unitNumber').inputMode='numeric';$('unitNumber').maxLength=6;$('unitNumber').placeholder='Six digit unit number';$('unitNumber2').closest('label').classList.toggle('hidden',false);if(!show){$('unitNumber').value='';$('unitNumber2').value=''}$('routeFields').classList.toggle('hidden',!route);$('trainRouteFrom').required=route;$('trainRouteTo').required=route;if(!route){$('trainRouteFrom').value='';$('trainRouteTo').value=''}}
