$('trainForm').addEventListener('submit',e=>{e.preventDefault();const job=String($('shiftJobNumber').value||'').trim().toUpperCase(),refresh=job==='REFRESH',specialActivity=['REFRESH','ROUTES','OTHER'].includes(job),noHeadcode=specialActivity;const route=/(PASS|TAXI)/i.test($('trainFrom').value),rawCode=$('trainCode').value.trim(),code=noHeadcode?'N/A':route?rawCode:cleanHead(rawCode),unit=specialActivity?'':$('unitNumber').value.replace(/\D/g,''),unit2=specialActivity?'':$('unitNumber2').value.replace(/\D/g,'');if(!noHeadcode&&(!code||(!route&&!/^[0-9][A-Z][0-9]{2}$/.test(code)))){status(route?'Enter a headcode or reference.':'Enter a valid four-character headcode, for example 1V50.');$('trainCode').focus();return}if(needsUnit($('trainFrom').value)&&!specialActivity&&unit.length!==6){status('Enter a six-digit unit number.');$('unitNumber').focus();return}if(needsUnit($('trainFrom').value)&&!specialActivity&&unit2&&unit2.length!==6){status('Second unit number must be six digits, or left blank.');$('unitNumber2').focus();return}const routeFrom=$('trainRouteFrom').value.trim(),routeTo=$('trainRouteTo').value.trim();if(route&&(!routeFrom||!routeTo)){status('Enter both the FROM and TO locations.');(!routeFrom?$('trainRouteFrom'):$('trainRouteTo')).focus();return}const trainRecord={from:$('trainFrom').value,headcode:code,unit:needsUnit($('trainFrom').value)&&!specialActivity?unit:'',unit2:needsUnit($('trainFrom').value)&&!specialActivity?unit2:'',routeFrom:route?routeFrom:'',routeTo:route?routeTo:'',addedAt:editingTrainIndex===null?stamp():(state.trains[editingTrainIndex]?.addedAt||stamp())};if(editingTrainIndex===null)state.trains.push(trainRecord);else state.trains[editingTrainIndex]={...state.trains[editingTrainIndex],...trainRecord};editingTrainIndex=null;$('trainDialog').close();$('trainDialog').querySelector('.dialoghead h2').textContent='Add train';$('trainSubmit').textContent='Add train';render();persist()});
