 if(type.value==='Defect'){updateDefectUnitField();$('relatedTrain')?.addEventListener('change',updateDefectUnitField);$('defectPvn')?.addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6)});}
 if(type.value==='Assist')$('assist-wheelchair')?.addEventListener('change',e=>{const seat=$('seat');if(!seat)return;if(e.target.checked){seat.value='WC space';seat.placeholder='WC space';}else if(seat.value.trim().toLowerCase()==='wc space'){seat.value='';seat.placeholder='e.g. 42';}});
 if(type.value==='Ticket acceptance'){ticketCustomOperator='';ticketCustomReason='';$('ticketOperator')?.addEventListener('change',e=>{const multiple=e.target.value==='Multiple';$('ticketMultipleOperators')?.classList.toggle('hidden',!multiple);if(multiple){ticketCustomOperator='';$('ticketOperatorCustom').textContent='Select all applicable operators below.'}else if(e.target.value==='Other'){openTicketCustomDialog('operator')}else{ticketCustomOperator='';$('ticketOperatorCustom').textContent=''}});$('ticketReason')?.addEventListener('change',e=>{if(e.target.value==='Other'){openTicketCustomDialog('reason')}else{ticketCustomReason='';$('ticketReasonCustom').textContent=''}})}
 if(type.value==='Train Diversion')$('diversionRoute')?.addEventListener('change',()=>{$('otherDiversionWrap').classList.toggle('hidden',$('diversionRoute').value!=='Other');if($('diversionRoute').value==='Other')$('otherDiversionRoute').focus()});if(type.value==='Full and standing')$('chooseFullStanding')?.addEventListener('click',openFullStandingDialog);
 const labels={'Incident':'Incident details','Control Message':'Control message','Reminder':'Reminder details','General Note':'General note','Incident Update':'Incident update details','Defect':'Defect description','Passenger Counts':'Additional information (optional)','Full and standing':'Additional information (optional)','Delay':'Nature of delay','Assist':'Nature of assistance'};
