$('ticketCustomCancel').addEventListener('click',()=>{$('ticketCustomDialog').close();const select=$(ticketCustomTarget==='operator'?'ticketOperator':'ticketReason');if(select)select.value='';ticketCustomTarget=''});$('ticketCustomClose').addEventListener('click',()=>$('ticketCustomCancel').click());$('ticketCustomForm').addEventListener('submit',e=>{e.preventDefault();const value=$('ticketCustomValue').value.trim();if(!value){$('ticketCustomValue').focus();return}if(ticketCustomTarget==='operator'){ticketCustomOperator=value;$('ticketOperatorCustom').textContent='Custom operator: '+value}else{ticketCustomReason=value;$('ticketReasonCustom').textContent='Custom reason: '+value}$('ticketCustomDialog').close();ticketCustomTarget=''});
