function beginArchiveEdit(record){if(!record)return false;if(archiveEditingRecord)return true;archiveActiveState={entries:state.entries,trains:state.trains};archiveRecordBackup={entries:JSON.parse(JSON.stringify(record.entries||[])),trains:JSON.parse(JSON.stringify(record.trains||[]))};archiveEditingRecord=record;state.entries=Array.isArray(record.entries)?record.entries:(record.entries=[]);state.trains=Array.isArray(record.trains)?record.trains:(record.trains=[]);return true}
function finishArchiveEdit(message='Archived shift updated.'){if(!archiveEditingRecord)return;const record=archiveEditingRecord,recordId=record.archiveId;const workingEntries=JSON.parse(JSON.stringify(state.entries||[])),workingTrains=JSON.parse(JSON.stringify(state.trains||[]));const previousEntries=archiveRecordBackup?.entries||[],previousTrains=archiveRecordBackup?.trains||[];record.entries=workingEntries;record.trains=workingTrains;record.updatedAt=stamp();archiveEditingRecord=null;state.entries=archiveActiveState.entries;state.trains=archiveActiveState.trains;archiveActiveState=null;let ok=persist(true);if(ok){try{const saved=JSON.parse(localStorage.getItem(STORE)||'{}'),savedRecord=(saved.archivedShifts||[]).find(x=>x.archiveId===recordId);ok=!!savedRecord&&Array.isArray(savedRecord.entries)&&savedRecord.entries.length===workingEntries.length&&Array.isArray(savedRecord.trains)&&savedRecord.trains.length===workingTrains.length}catch{ok=false}}if(!ok){record.entries=previousEntries;record.trains=previousTrains;record.updatedAt=undefined;try{localStorage.setItem(STORE,JSON.stringify(snapshot()))}catch(err){console.warn('Archive rollback could not be persisted',err)}}archiveRecordBackup=null;renderArchivedShifts();if(ok){openArchivedShiftReadOnly(record);status(message+' Saved to this device.')}else{openArchivedShiftReadOnly(record);status('The archive change could not be verified as saved. The original archived entries have been restored. Please check device storage and try again.')}}
function cancelArchiveEdit(){if(!archiveEditingRecord)return;state.entries=archiveActiveState.entries;state.trains=archiveActiveState.trains;archiveEditingRecord=null;archiveActiveState=null;archiveRecordBackup=null;openArchivedShiftReadOnly(state.archivedShifts.find(x=>x.archiveId===selectedArchiveRecordId));}
