function incidentReportAuto(entry){const train=state.trains.find(t=>(entry.relatedTrainId&&t.id===entry.relatedTrainId)||(linkedHeadcode(entry)&&String(t.headcode||'').toUpperCase()===linkedHeadcode(entry)))||null;const ts=new Date(entry.timestamp);const time=Number.isNaN(ts.getTime())?'':ts.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});const activity=train?(String(train.from||'').replace(/^\W+/, '').toLowerCase()==='working'?'working':String(train.from||'').replace(/^\W+/, '').toLowerCase()):'';const incidentDate=Number.isNaN(ts.getTime())?dateDMY($('shiftDate').value):ts.toLocaleDateString('en-GB');const updates=(entry.updates||[]).map(u=>`Update (${fmt(u.timestamp)}): ${u.text}`).join('\n\n');return {...{date:incidentDate,time,activity,originDestination:'',startEndLocation:'',headcode:linkedHeadcode(entry),turnNumber:$('shiftJobNumber').value.trim(),workingAlongside:'',otherInvolved:'',carriages:'',trainType:'',formation:train?[train.unit,train.unit2].filter(Boolean).join(' + '):'',tmLocation:'',incidentTrainLocation:entry.incidentLocation||'',platform:'',journeyDirection:'',whatHappened:[String(entry.text||'').trim(),updates].filter(Boolean).join('\n\n'),personsDescription:'',witnesses:'',bwv:'',bwvCamera:'',serviceImpact:'',closingRemarks:'',policeAttendance:'',otherServices:''},...(entry.reportDetails||{})};}
function openIncidentReport(entryIndex){const entry=state.entries[entryIndex];if(!entry||entry.type!=='Incident')return;incidentReportEntryIndex=entryIndex;const values=incidentReportAuto(entry);let html='',section='';incidentReportFieldDefs.forEach(f=>{if(f.section&&f.section!==section){section=f.section;html+=`<h3 class="incident-report-section">${esc(section)}</h3>`}const value=values[f.key]||'';const missing=!value;const label=`<span class="${missing?'missing-report-label':''}">${esc(f.label)}</span>`;const multiline=['whatHappened','personsDescription','witnesses','serviceImpact','closingRemarks','policeAttendance','otherServices','workingAlongside','otherInvolved'].includes(f.key);html+=`<label class="incident-report-field">${label}${multiline?`<textarea name="${f.key}" rows="${f.key==='whatHappened'?5:3}" placeholder="${esc(f.hint)}">${esc(value)}</textarea>`:`<input name="${f.key}" value="${esc(value)}" placeholder="${esc(f.hint)}">`}</label>`});$('incidentReportFields').innerHTML=html;$('incidentReportDetailsDialog').showModal();}
function buildIncidentReport(entry,values){const get=k=>String(values[k]||'').trim();const lines=[];if(entry.incidentRef)lines.push(`Incident reference: ${entry.incidentRef}`);const intro=[get('date')&&`On ${get('date')}`,get('time')&&`at approximately ${get('time')}`,get('activity')&&`I was ${get('activity')}`,get('originDestination')&&`the ${get('originDestination')}`,get('headcode')&&`with Headcode ${get('headcode')}`,get('turnNumber')&&`as part of Train Manager Turn ${get('turnNumber')}`].filter(Boolean).join(' ');if(intro)lines.push(intro+'.');const add=(heading,parts)=>{const vals=parts.filter(Boolean);if(vals.length)lines.push('',heading,...vals)};add('SERVICE AND DUTY',[get('startEndLocation')&&`I worked this train from ${get('startEndLocation')}.`,get('workingAlongside')&&`I was working alongside ${get('workingAlongside')}.`,get('otherInvolved')&&`Also involved was ${get('otherInvolved')}.`,get('carriages')&&`The train was formed of ${get('carriages')} carriages.`,get('trainType')&&`This was a ${get('trainType')}.`,get('formation')&&`Train formation: ${get('formation')}.`,get('tmLocation')&&`I was located at ${get('tmLocation')}.`,get('incidentTrainLocation')&&`At the time of the incident the train was at ${get('incidentTrainLocation')}.`,get('platform')&&`Platform ${get('platform')}.`,get('journeyDirection')&&`Travelling from ${get('journeyDirection')}.`]);add('WHAT HAPPENED?',[get('whatHappened')]);add('WHO WAS INVOLVED?',[get('personsDescription')]);add('WITNESSES',[get('witnesses')]);add('BODY WORN VIDEO',[get('bwv'),get('bwvCamera')&&`BWV camera serial number: ${get('bwvCamera')}`]);add('SERVICE IMPACT',[get('serviceImpact')]);add('CLOSING REMARKS / WHAT HAPPENED AFTER THE INCIDENT?',[get('closingRemarks')]);add('BTP / LOCAL POLICE ATTENDANCE',[get('policeAttendance')]);add('OTHER EMERGENCY SERVICES / NETWORK RAIL',[get('otherServices')]);return lines.join('\n');}
