function delayMinutesValue(e){if(e?.type!=='Delay')return null;const stored=e.delayMinutes;const match=String(e.text||'').match(/(?:^|\n)\s*Delay:\s*(\d+(?:\.\d+)?)\s*minutes?/i);const value=stored!==undefined&&stored!==null&&stored!==''?Number(stored):(match?Number(match[1]):NaN);return Number.isFinite(value)?value:null}
function isDelayOverTen(e){return delayMinutesValue(e)>10}
function entryLabel(e){return e.type==='Incident'?`🚨 ${incidentTitle(e)}${e.incidentRef?' · '+e.incidentRef:''}`:({'Lost Property':'🧳 Lost Property','Defect':'🔧 Defect','Passenger Counts':'#️⃣ Passenger Counts','Ticket acceptance':'🎟️ Ticket acceptance','Control Message':'📟 Control Message','Delay':'⏱️ Delay','Train Diversion':'🚧 Train Diversion','Full and standing':'🛑 Full and standing','Assist':'🦮♿ Assist','Reminder':'ℹ️ Reminder','General Note':'📝 General Note','Late book off':'⌚️ Late book off'}[e.type]||e.type)}
function commissionShiftTotals(entries){
 const rows=(entries||[]).filter(e=>e.type==='Ticket commission');let scans=0,sales=0,commission=0;
 rows.forEach(e=>{
  const t=String(e.text||'');const data=e.commission&&typeof e.commission==='object'?e.commission:{};
  const match=(patterns)=>{for(const pattern of patterns){const m=t.match(pattern);if(m)return Number(String(m[1]).replace(/,/g,''));}return null};
  const parsedScans=match([/(?:Ticket\s+)?scans?\s*:?\s*([\d,]+)/i,/(?:Shift\s+)?scans?\s*:?\s*([\d,]+)/i]);
  const parsedSales=match([/Ticket\s+sales\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i,/Sales\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]);
  const parsedTotal=match([/(?:TOTAL\s+COMMISSION|Commission\s+for\s+shift)\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]);
  const nScans=Number(data.scans??data.shiftScans??data.ticketScans??e.scans??parsedScans??0);
  const nSales=Number(data.sales??data.ticketSales??e.sales??parsedSales??0);
  const storedTotal=data.total??data.totalCommission??data.commission??e.totalCommission;
  let nCommission=Number(storedTotal);
  if(!Number.isFinite(nCommission)||storedTotal===undefined||storedTotal===null){
   const scanPart=Number(data.scanCommission??match([/Scan\s+commission\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]));
   const salesPart=Number(data.salesCommission??match([/Sales\s+commission\s*:?\s*£?\s*([\d,]+(?:\.\d{1,2})?)/i]));
   if(Number.isFinite(scanPart)||Number.isFinite(salesPart))nCommission=(Number.isFinite(scanPart)?scanPart:0)+(Number.isFinite(salesPart)?salesPart:0);
   else if(parsedTotal!==null)nCommission=parsedTotal;
   else {const per=Number(data.perScan??data.commissionPerScan),pct=Number(data.salesPercent??data.salesCommissionRate);nCommission=(Number.isFinite(per)?nScans*per:0)+(Number.isFinite(pct)?nSales*pct/100:0)}
  }
  scans+=Number.isFinite(nScans)?nScans:0;sales+=Number.isFinite(nSales)?nSales:0;commission+=Number.isFinite(nCommission)?nCommission:0;
 });
 return {hasEntries:rows.length>0,scans,sales,commission};
}
function commissionReportLines(entries){const c=commissionShiftTotals(entries);return c.hasEntries?[ 'COMMISSION REPORT','-----------------',`Shift scans: ${c.scans}`,`Ticket sales: £${c.sales.toFixed(2)}`,`Commission for shift: £${c.commission.toFixed(2)}`]:[]}
function report(){
 const s=snapshot();
 const divider='────────────────────────────────────────';
 const lines=[
  'XC SHIFTAPP | OPERATIONAL SHIFT LOG',divider,
  `DATE          ${dateDMY(s.shift.date)}`,
  ...(s.shift.jobNumber?[`JOB NUMBER    ${s.shift.jobNumber}`]:[]),...(s.shift.bookOn?[`BOOK ON       ${s.shift.bookOn}`]:[]),...(s.shift.bookOff?[`BOOK OFF      ${s.shift.bookOff}`]:[]),...(s.shift.bookOn&&s.shift.bookOff?[`SHIFT LENGTH  ${shiftLengthText(s.shift.bookOn,s.shift.bookOff)}`]:[]),...(includePayInReports()&&shiftPayEstimate()? [`ESTIMATED PAY £${shiftPayEstimate().pay.toFixed(2)} (${shiftPayEstimate().sunday?'Sunday':'Monday–Saturday'} rate £${shiftPayEstimate().rate.toFixed(2)}/hour)`]:[]),
  ...(s.shift.notes?['','SHIFT NOTES',s.shift.notes]:[]),
  ...(commissionReportLines(s.entries).length?['',...commissionReportLines(s.entries)]:[]),
  '',divider,'TRAINS',divider,
  ...(s.trains.length?s.trains.map((t,i)=>`${i+1}. ${[t.from,t.headcode].filter(Boolean).join('  |  ')}${/(PASS|TAXI)/i.test(t.from||'')?[t.routeFrom&&`\n   From: ${t.routeFrom}`,t.routeTo&&`\n   To: ${t.routeTo}`].filter(Boolean).join(''):needsUnit(t.from)?(t.unit?`\n   Unit: ${t.unit}${t.unit2?' + '+t.unit2:''}`:''):''}`):['No trains recorded']),
  '',divider,'OPERATIONAL LOG / OCCURRENCES',divider,
  ...(s.entries.length?groupedEntries(s.entries).map((item,i)=>item.kind==='defectGroup'?`${String(i+1).padStart(2,'0')}  ${defectGroupPlain(item)}`:item.kind==='passengerGroup'?`${String(i+1).padStart(2,'0')}  ${passengerGroupPlain(item)}`:`${String(i+1).padStart(2,'0')}  ${entryLabel(item.entry)}\n     ${fmt(item.entry.timestamp)}\n${reportLines(entryDetails(item.entry)).map(x=>'     '+x).join('\n')}`):['No entries recorded']),
  '',divider,`Generated by Staff Shift App ${VERSION}`
 ];
 return lines.join('\n');
}
