 const commission=commissionShiftTotals(s.entries);const commissionBlock=commission.hasEntries?`<h2 style="${heading}">Commission report</h2>${table(['COMMISSION SUMMARY','SHIFT TOTAL'],[['Shift scans',String(commission.scans)],['Ticket sales',`£${commission.sales.toFixed(2)}`],['Commission for shift',`£${commission.commission.toFixed(2)}`]])}`:'';
