function openArchivedShiftReadOnly(record){
 if(!record)return;selectedArchiveRecordId=record.archiveId||'';
 const shift=record.shift||{}, trains=Array.isArray(record.trains)?record.trains:[], entries=Array.isArray(record.entries)?record.entries:[];
 archiveViewEntries=entries.slice().sort((a,b)=>String(a.timestamp||'').localeCompare(String(b.timestamp||'')));
 $('archiveViewTitle').textContent=`Archived shift · ${dateDMY(shift.date)} · ${shift.jobNumber||'No turn number'}`;
 const trainHtml=trains.length?trains.map(t=>`<div class="archive-view-train"><strong>${esc(t.headcode||'No headcode')}</strong><span>${esc(t.from||'Working')}${needsUnit(t.from)?' · '+esc([t.unit,t.unit2].filter(Boolean).join(' + ')||'Unit not recorded'):''}${t.routeFrom||t.routeTo?' · '+esc(t.routeFrom||'—')+' → '+esc(t.routeTo||'—'):''}</span></div>`).join(''):'<p class="muted">No trains recorded.</p>';
 const entryHtml=archiveViewEntries.length?archiveViewEntries.map((e,entryIndex)=>{
  let hc=String(e.relatedTrainHeadcode||e.headcode||e.trainHeadcode||'').trim().toUpperCase();
  if(!/^\d[A-Z]\d{2}$/.test(hc)&&e.relatedTrainId){const t=trains.find(x=>x.id&&x.id===e.relatedTrainId);hc=String(t?.headcode||'').toUpperCase()}
  if(!/^\d[A-Z]\d{2}$/.test(hc)){const m=String(e.relatedTrainLabel||e.text||'').match(/\b(\d[A-Z]\d{2})\b/i);hc=m?m[1].toUpperCase():''}
  const text=String(e.text||'No details recorded').replace(/\\n/g,'\n');
  const updates=Array.isArray(e.updates)?e.updates.map(u=>`<p class="archive-view-update"><b>Update · ${esc(fmt(u.timestamp))}</b><br>${esc(u.text||'').replace(/\n/g,'<br>')}</p>`).join(''):'';
  return `<article class="archive-view-entry"><div class="archive-view-entry-head"><strong>${esc(entryLabel(e))}${hc?` <b class="headcode-highlight">[${esc(hc)}]</b>`:''}</strong><div class="archive-view-entry-tools"><time>${esc(fmt(e.timestamp))}</time><button type="button" class="archive-copy-entry" data-copy-archive-entry="${entryIndex}" aria-label="Copy this archived entry" title="Copy entry">📋</button><button type="button" class="secondary small" data-edit-archive-entry="${entryIndex}">Edit</button><button type="button" class="danger small" data-delete-archive-entry="${entryIndex}" aria-label="Delete this archived entry">Delete</button></div></div><p>${esc(text).replace(/\n/g,'<br>')}</p>${updates}${e.photo?`<img class="archive-view-photo" src="${e.photo}" alt="Attached lost property photo">`:''}</article>`;
 }).join(''):'<p class="muted">No operational log entries recorded.</p>';
 $('archiveViewContent').innerHTML=`<div class="archive-view-actions"><button type="button" class="primary full" id="archiveAddEntry">＋ Add issue / log entry</button></div><section class="archive-view-section"><h3>Shift details</h3><p><b>Date:</b> ${esc(dateDMY(shift.date))}</p><p><b>Job number:</b> ${esc(shift.jobNumber||'—')}</p>${shift.bookOn?`<p><b>Book on:</b> ${esc(shift.bookOn)}</p>`:''}${shift.bookOff?`<p><b>Book off:</b> ${esc(shift.bookOff)}</p>`:''}${shift.bookOn&&shift.bookOff?`<p><b>Shift length:</b> ${esc(shiftLengthText(shift.bookOn,shift.bookOff))}</p>`:''}${shift.notes?`<p><b>Shift notes</b><br>${esc(shift.notes).replace(/\n/g,'<br>')}</p>`:''}</section><section class="archive-view-section"><h3>Trains (${trains.length})</h3>${trainHtml}</section><section class="archive-view-section"><h3>Operational Log / Occurrences (${entries.length})</h3>${entryHtml}</section>`;
 $('archiveViewDialog').showModal();
}
$('archiveViewContent').addEventListener('click',async e=>{const add=e.target.closest('#archiveAddEntry'),edit=e.target.closest('[data-edit-archive-entry]'),del=e.target.closest('[data-delete-archive-entry]'),button=e.target.closest('[data-copy-archive-entry]');if(add){const record=state.archivedShifts.find(x=>x.archiveId===selectedArchiveRecordId);if(!record)return;beginArchiveEdit(record);$('archiveViewDialog').close();$('addIssue').click();return}if(edit){const record=state.archivedShifts.find(x=>x.archiveId===selectedArchiveRecordId);if(!record)return;beginArchiveEdit(record);const entry=archiveViewEntries[Number(edit.dataset.editArchiveEntry)],index=state.entries.indexOf(entry);if(index<0)return;$('archiveViewDialog').close();openEditEntry(index);$('editEntryType').textContent='Archived · '+$('editEntryType').textContent;return}if(del){const record=state.archivedShifts.find(x=>x.archiveId===selectedArchiveRecordId);const entry=archiveViewEntries[Number(del.dataset.deleteArchiveEntry)];if(!record||!entry)return;if(!await customConfirm({title:'Delete archived log entry?',message:`Permanently delete this ${entry.type||'log'} entry from ${dateDMY(record.shift?.date)}? This cannot be undone.`,accept:'Delete entry'}))return;beginArchiveEdit(record);const index=state.entries.indexOf(entry);if(index<0){cancelArchiveEdit();return}state.entries.splice(index,1);finishArchiveEdit('Archived log entry deleted.');return}if(button){const index=Number(button.dataset.copyArchiveEntry),entry=archiveViewEntries[index];if(entry)await copyEntryToClipboard(entry)}});
